mapper.select:
SELECT * FROM (
    SELECT a.*, ROWNUM rnum FROM (
       SELECT posting_idx AS postingIdx, title, employer, pay, pay_type AS payType, location, createdDate,
              category, work_period AS workPeriod, work_days AS workDays, 
              start_time AS startTime, end_time AS endTime
       FROM job_posting 
       ORDER BY posting_idx DESC
    ) a WHERE ROWNUM <= #{offset} + #{size}
) WHERE rnum > #{offset}
